void NativeDclCore::registerModule(
    jsi::Runtime &rt, std::shared_ptr<react::CallInvoker> callInvoker) {
  auto invoker =
      std::make_shared<uniffi_runtime::UniffiCallInvoker>(callInvoker);
  auto tm = std::make_shared<NativeDclCore>(rt, invoker);
  auto obj = rt.global().createFromHostObject(rt, tm);
  rt.global().setProperty(rt, "NativeDclCore", obj);
}

void NativeDclCore::unregisterModule(jsi::Runtime &rt) {
  uniffi::dcl_core::registry::clearRegistry();
}

jsi::Value NativeDclCore::get(jsi::Runtime &rt, const jsi::PropNameID &name) {
  try {
    return jsi::Value(rt, props.at(name.utf8(rt)));
  } catch (std::out_of_range &) {
    return jsi::Value::undefined();
  }
}

std::vector<jsi::PropNameID> NativeDclCore::getPropertyNames(jsi::Runtime &rt) {
  std::vector<jsi::PropNameID> rval;
  for (auto &[key, value] : props) {
    rval.push_back(jsi::PropNameID::forUtf8(rt, key));
  }
  return rval;
}

void NativeDclCore::set(jsi::Runtime &rt, const jsi::PropNameID &name,
                        const jsi::Value &value) {
  props.insert_or_assign(name.utf8(rt), &value);
}

NativeDclCore::~NativeDclCore() {
  // Cleanup for callback function RustFutureContinuationCallback
  uniffi::dcl_core::cb::rustfuturecontinuationcallback::cleanup();
  // Cleanup for callback function ForeignFutureDroppedCallback
  uniffi::dcl_core::cb::foreignfuturedroppedcallback::cleanup();
  // Cleanup for "free" callback function CallbackInterfaceFree
  uniffi::dcl_core::st::vtablecallbackinterfaceapplistener::
      vtablecallbackinterfaceapplistener::free::cleanup();
  uniffi::dcl_core::cb::callbackinterfaceclone::
      vtablecallbackinterfaceapplistener::cleanup();
  uniffi::dcl_core::cb::callbackinterfaceapplistenermethod0::
      vtablecallbackinterfaceapplistener::cleanup();
  uniffi::dcl_core::cb::callbackinterfaceapplistenermethod1::
      vtablecallbackinterfaceapplistener::cleanup();
  uniffi::dcl_core::cb::callbackinterfaceapplistenermethod2::
      vtablecallbackinterfaceapplistener::cleanup();
  uniffi::dcl_core::cb::callbackinterfaceapplistenermethod3::
      vtablecallbackinterfaceapplistener::cleanup();
}

